let devices = ['ac', 'light', 'fridge', 'laundry', 'dehumidifier', 'cooker', 'thermostat'];


// ---------------- ENERGY ----------------
// Sum cumulative kWh from devices
let totalKWh = devices.reduce(
    (sum, d) => sum + (flow.get(`energy.${d}`) || 0),
    0
);

// ---------------- OUTPUT ----------------
msg.totalEnergy = `${totalKWh.toFixed(3)} kWh`;

// Optional: numeric outputs for charts / gauges

msg.totalEnergyKWh = parseFloat(totalKWh.toFixed(3));

// ---------------- NODE STATUS ----------------
let color = totalKWh === 0 ? "grey" : "green";
let shape = totalKWh === 0 ? "ring" : "dot";
let text = `Energy: ${totalKWh.toFixed(3)} kWh`;

node.status({ fill: color, shape, text });

return msg;

// === Air Conditioner Telemetry Simulator (Smart Plug Controlled) ===

// --- Check Smart Plug state ---
const plugState = global.get('acState') || 'off';
if (plugState !== 'on') {
    node.status({ fill: 'grey', shape: 'ring', text: 'Plug OFF – telemetry paused' });
    return null;
}

// --- Environment values ---
let envTemp = parseFloat(msg.payload.temperature ?? 25);
let envHumidity = parseFloat(msg.payload.humidity ?? 50);

// --- Simulation step: 1 execution = 1 simulated minute ---
const tickDuration = 60; // seconds (simulated)

// --- Persistent setpoint (changes every 60 simulated minutes = 1 hour) ---
let setpoint = flow.get('ac.setpoint');
let setpointTimer = flow.get('ac.setpointTimer') || 0;

setpointTimer += 1; // 1 tick = 1 minute

if (setpoint === undefined || setpoint === null || setpointTimer >= 60) {
    // Random setpoint each simulated hour (optional)
    setpoint = Math.floor(16 + Math.random() * 15); // 16–30°C
    setpointTimer = 0;
}

// If you want ALWAYS 23°C, keep this line and remove randomization above:
// setpoint = 23;
setpoint = 23;

// --- Persistent current temperature (don’t reset each tick) ---
let current = flow.get('ac.currentTemp');
if (current === undefined || current === null) current = envTemp;

// --- Natural drift + pull toward environment ---
current += (Math.random() * 0.3 - 0.15); // small drift ±0.15°C
current += (envTemp - current) * 0.05;   // gently pull toward env

// --- Determine AC mode ---
let mode = 'idle';
let currentPower = 0;

// Deadband around setpoint
const deadband = 1;

if (current > setpoint + deadband) {
    mode = 'cool';
    currentPower = 1200;
    current -= 0.4; // cooling effect per tick
} else if (current < setpoint - deadband) {
    mode = 'heat';
    currentPower = 2000;
    current += 0.4; // heating effect per tick
}

// --- Energy tracking (kWh) ---
let energy = flow.get('energy.ac') || 0;
function wattToKwh(powerWatts, seconds) {
    return (powerWatts / 1000) * (seconds / 3600);
}
if (currentPower > 0) energy += wattToKwh(currentPower, tickDuration);

// --- Save state ---
flow.set('ac.setpoint', setpoint);
flow.set('ac.setpointTimer', setpointTimer);
flow.set('ac.currentTemp', current);
flow.set('energy.ac', energy);

// --- Node status feedback ---
let color = "green";
let shape = "ring";
let text = `Idle | ${current.toFixed(1)}°C → ${setpoint}°C | 0 W`;

if (mode === 'cool') {
    color = "blue";
    shape = "dot";
    text = `Cooling | ${current.toFixed(1)}°C → ${setpoint}°C | ${currentPower} W`;
} else if (mode === 'heat') {
    color = "red";
    shape = "dot";
    text = `Heating | ${current.toFixed(1)}°C → ${setpoint}°C | ${currentPower} W`;
}

node.status({ fill: color, shape, text });

// --- Telemetry output ---
msg.payload = {
    device: "ac",
    power: plugState,                    // on/off from smart plug
    temperature: parseFloat(current.toFixed(1)),
    humidity: envHumidity,
    setpoint: setpoint,
    mode: mode,
    currentPower: currentPower,          // instantaneous Watts
    energyUsed: parseFloat(energy.toFixed(3)), // cumulative kWh
    unit: "C",
    timestamp: new Date().toISOString()
};

msg.parameters = {homeId : 1};

return msg;

// === Smart Light Telemetry Simulator (Controlled by Smart Plug) ===

// --- Check Smart Plug state first ---
const plugState = global.get('lightState') || 'off';
if (plugState !== 'on') {
    node.status({ fill: 'grey', shape: 'ring', text: 'Plug OFF – telemetry paused' });
    return null;
}

// --- Environment info ---
let envTemp = parseFloat(msg.payload.temperature ?? 22);
let envHumidity = parseFloat(msg.payload.humidity ?? 45);
let envLight = parseFloat(msg.payload.lightIntensity ?? 50);

// --- Threshold for turning lights ON/OFF (0–100) ---
const lightThreshold = 30;
let state = envLight < lightThreshold ? "ON" : "OFF";

// --- Light behavior when ON ---
let brightness = state === "ON" ? Math.floor(50 + Math.random() * 51) : 0; // 50–100%
const colors = ["#FFFFFF", "#FFAA00", "#00FFAA", "#AA00FF"];
let color = colors[Math.floor(Math.random() * colors.length)];
let colorTemperature = Math.floor(2700 + Math.random() * (6500 - 2700));
const modes = ["normal", "reading", "nightlight", "ambient", "effect"];
let mode = modes[Math.floor(Math.random() * modes.length)];
let effect = mode === "effect"
    ? ["rainbow", "pulse", "candle"][Math.floor(Math.random() * 3)]
    : "";

// --- Simulation step: 1 execution = 1 simulated minute ---
const tickSeconds = 60; // seconds (simulated)

// --- Power & Energy tracking (kWh cumulative) ---
let energy = flow.get('energy.light') || 0;
const currentPower = state === "ON" ? (8 + Math.random() * 2) : 0; // Watts

energy += (currentPower / 1000) * (tickSeconds / 3600); // kWh
flow.set('energy.light', energy); // keep full precision; round only for display

// --- Node status for dashboard ---
let colorStatus = state === "ON" ? "green" : "red";
let shape = state === "ON" ? "dot" : "ring";
let text = `${state} | ${currentPower.toFixed(1)} W`;

node.status({ fill: colorStatus, shape, text });

// --- Telemetry output ---
msg.payload = {
    device: "light",
    power: plugState, // smart plug on/off
    state,
    brightness,
    color,
    colorTemperature,
    mode,
    effect,
    currentPower: parseFloat(currentPower.toFixed(1)),      // instantaneous W
    energyUsed: parseFloat(energy.toFixed(3)),              // cumulative kWh
    voltage: 230,
    environmentTemp: parseFloat(envTemp),
    environmentHumidity: parseFloat(envHumidity),
    environmentLight: parseFloat(envLight),
    timestamp: new Date().toISOString()
};
msg.parameters = {homeId: 1};

return msg;

// === Fridge & Freezer Telemetry Simulator (Safe Temperatures) ===

// Desired temps (user setpoints)
const fridgeSet = flow.get("fridge.setTemp") ?? 4;      // °C
const freezerSet = flow.get("freezer.setTemp") ?? -18;  // °C

// Current temps (persist across ticks)
let fridgeTemp = flow.get("fridge.currentTemp");
let freezerTemp = flow.get("freezer.currentTemp");

if (fridgeTemp === undefined || fridgeTemp === null) fridgeTemp = fridgeSet + (Math.random() * 2 - 1);
if (freezerTemp === undefined || freezerTemp === null) freezerTemp = freezerSet + (Math.random() * 2 - 1);

// --- Simulation step: 1 execution = 1 simulated minute ---
const tickSeconds = 60; // seconds (simulated)

// --- Door status simulation (10% chance door is open) ---
let doorStatus = "closed";
if (Math.random() < 0.1) {
    doorStatus = Math.random() > 0.5 ? "fridge_open" : "freezer_open";
}

// --- Natural drift (slightly worse when door open) ---
let fridgeDrift = (Math.random() * 0.4 - 0.2);   // ±0.2°C
let freezerDrift = (Math.random() * 0.6 - 0.3);  // ±0.3°C

if (doorStatus !== "closed") {
    // Door open warms things up faster (simple model)
    fridgeDrift += 0.25;
    freezerDrift += 0.35;
}

fridgeTemp += fridgeDrift;
freezerTemp += freezerDrift;

// --- Compressor state logic ---
let compressor = "OFF";
let currentPower = 5; // idle watts baseline

// If door open, idle/lighting/fan slightly higher
if (doorStatus !== "closed") currentPower = 20;

if (fridgeTemp > fridgeSet + 1) {
    compressor = "ON";
    fridgeTemp -= 0.3;
    if (fridgeTemp < fridgeSet) fridgeTemp = fridgeSet;
    currentPower = 150;
}

if (freezerTemp > freezerSet + 1) {
    compressor = "ON";
    freezerTemp -= 0.5;
    if (freezerTemp < freezerSet) freezerTemp = freezerSet;
    currentPower = 150;
}

// --- Energy usage tracking (kWh cumulative) ---
let energy = flow.get("energy.fridge") || 0;
energy += (currentPower / 1000) * (tickSeconds / 3600);
flow.set("energy.fridge", energy);

// --- Save temps for next tick ---
flow.set("fridge.currentTemp", fridgeTemp);
flow.set("freezer.currentTemp", freezerTemp);

// --- Node status visual feedback ---
let color = "green";
let shape = "ring";
let text = `Stable | ${fridgeTemp.toFixed(1)}°C / ${freezerTemp.toFixed(1)}°C | ${currentPower} W`;

if (doorStatus !== "closed") {
    color = "red";
    shape = "dot";
    text = `⚠️ Door Open (${doorStatus.replace("_", " ")}) | ${currentPower} W`;
} else if (compressor === "ON") {
    color = "blue";
    shape = "dot";
    text = `Cooling ON | ${fridgeTemp.toFixed(1)}°C / ${freezerTemp.toFixed(1)}°C | ${currentPower} W`;
}

node.status({ fill: color, shape, text });

// --- Telemetry payload ---
msg.payload = {
    device: "fridge",
    power: compressor, // compressor ON/OFF
    mode: "normal",
    fridgeTemp: parseFloat(fridgeTemp.toFixed(1)),
    freezerTemp: parseFloat(freezerTemp.toFixed(1)),
    doorStatus,
    humidityControl: ["low", "medium", "high"][Math.floor(Math.random() * 3)],
    currentPower, // instantaneous W
    energyUsed: parseFloat(energy.toFixed(3)), // cumulative kWh
    alarms: doorStatus !== "closed" ? ["door_open"] : [],
    timestamp: new Date().toISOString()
};
msg.parameters = { homeId: 1 };

return msg;

// --- Washing Machine Cycle Simulator (restart when remainingTime hits 0) ---
// What it does:
// - Runs a normal multi-phase washing cycle
// - Publishes AsyncAPI-compatible payload fields
// - Shows TOTAL remaining time for the whole cycle (minutes)
// - When TOTAL remaining time reaches 0 (cycle completed), it automatically starts a new cycle

// ----------------------------
// Simulation scale (seconds per tick)
// ----------------------------
const scale = global.get("simulationScale") || 60;   // seconds per tick
const tickSeconds = 1 * scale;

// ----------------------------
// Smart plug / power gate
// ----------------------------
const plugState = global.get("laundryState") || "off";
if (plugState !== "on") {
  node.status({ fill: "grey", shape: "ring", text: "Plug OFF – cycle paused" });
  return null;
}

// ----------------------------
// Config
// ----------------------------
const modeDurationsMin = {
  eco:      { filling: 5, washing: 60, rinsing: 15, spinning: 10, drying: 30 },
  normal:   { filling: 5, washing: 45, rinsing: 15, spinning: 10, drying: 20 },
  quick:    { filling: 3, washing: 20, rinsing: 10, spinning: 5,  drying: 10 },
  heavy:    { filling: 5, washing: 75, rinsing: 20, spinning: 15, drying: 40 },
  delicate: { filling: 5, washing: 30, rinsing: 15, spinning: 5,  drying: 10 }
};

const phasePower = {
  filling: 50,
  washing: 500,
  rinsing: 300,
  spinning: 800,
  drying: 2000
};

const phases = ["filling", "washing", "rinsing", "spinning", "drying"];

// Helpers
function minToSec(min) { return Math.round(min * 60); }
function clamp(n, lo, hi) { return Math.max(lo, Math.min(hi, n)); }
function secondsToCeilMinutes(sec) { return Math.ceil(sec / 60); }

// TOTAL remaining time for whole cycle (seconds)
function totalRemainingSeconds(mode, phase, remainingSeconds) {
  let total = remainingSeconds;
  const idx = phases.indexOf(phase);
  if (idx === -1) return total;
  for (let i = idx + 1; i < phases.length; i++) {
    total += minToSec(modeDurationsMin[mode][phases[i]]);
  }
  return total;
}

// Pick random mode
function pickRandomMode() {
  const modes = Object.keys(modeDurationsMin);
  return modes[Math.floor(Math.random() * modes.length)];
}

// Start cycle helper
function startNewCycle() {
  const newMode = pickRandomMode();
  const newPhase = "filling";
  const newRemainingSeconds = minToSec(modeDurationsMin[newMode][newPhase]);

  flow.set("laundry.mode", newMode);
  flow.set("laundry.phase", newPhase);
  flow.set("laundry.remainingSeconds", newRemainingSeconds);
  flow.set("laundry.running", true);

  // reset counters for each cycle (comment out if you want cumulative across cycles)
  flow.set("laundry.energyKwh", 0);
  flow.set("laundry.waterLiters", 0);

  return { newMode, newPhase, newRemainingSeconds };
}

// ----------------------------
// Load persistent state
// ----------------------------
let mode = flow.get("laundry.mode") || "normal";
let phase = flow.get("laundry.phase") || "idle";
let remainingSeconds = flow.get("laundry.remainingSeconds") || 0;

let running = flow.get("laundry.running");
if (typeof running !== "boolean") running = true;

let energyKwh = flow.get("laundry.energyKwh") || 0;
let waterLiters = flow.get("laundry.waterLiters") || 0;

// ----------------------------
// Initialize if first run / idle
// ----------------------------
if (phase === "idle" || !phases.includes(phase) || remainingSeconds <= 0) {
  const started = startNewCycle();
  mode = started.newMode;
  phase = started.newPhase;
  remainingSeconds = started.newRemainingSeconds;

  energyKwh = 0;
  waterLiters = 0;
}

// ----------------------------
// Progress current phase timer
// ----------------------------
if (running) {
  remainingSeconds = clamp(remainingSeconds - tickSeconds, 0, 10 ** 12);

  // When current phase ends, move to next phase
  if (remainingSeconds === 0) {
    const idx = phases.indexOf(phase);

    if (idx >= 0 && idx < phases.length - 1) {
      phase = phases[idx + 1];
      remainingSeconds = minToSec(modeDurationsMin[mode][phase]);
    } else {
      // End of last phase -> cycle completed
      phase = "completed";
      running = false;
      remainingSeconds = 0;
    }
  }
}

// ----------------------------
// If TOTAL remaining time is 0 => restart immediately
// ----------------------------
const totalRemaining = (phase === "completed")
  ? 0
  : totalRemainingSeconds(mode, phase, remainingSeconds);

if (totalRemaining === 0) {
  const restarted = startNewCycle();
  mode = restarted.newMode;
  phase = restarted.newPhase;
  remainingSeconds = restarted.newRemainingSeconds;

  energyKwh = 0;
  waterLiters = 0;
}

// ----------------------------
// Power, energy, water
// ----------------------------
const currentPowerW = (running && phases.includes(phase)) ? (phasePower[phase] || 0) : 0;

energyKwh += (currentPowerW / 1000) * (tickSeconds / 3600);

if (running && ["filling", "washing", "rinsing"].includes(phase)) {
  waterLiters += (Math.random() * 0.5) * (tickSeconds / 60);
}

// ----------------------------
// Simulated values
// ----------------------------
const waterTemp = (phase === "washing" && running) ? 40 + Math.random() * 10 : 25;
const spinSpeed = (phase === "spinning" && running) ? 800 + Math.floor(Math.random() * 400) : 0;
const loadWeight = 5 + Math.random() * 3;
const doorStatus = (running || phase === "completed") ? "locked" : "closed";

// ----------------------------
// Persist state
// ----------------------------
flow.set("laundry.mode", mode);
flow.set("laundry.phase", phase);
flow.set("laundry.remainingSeconds", remainingSeconds);
flow.set("laundry.running", running);
flow.set("laundry.energyKwh", energyKwh);
flow.set("laundry.waterLiters", waterLiters);

// ----------------------------
// Remaining time (minutes) for AsyncAPI
// ----------------------------
const minutesLeft = secondsToCeilMinutes(totalRemainingSeconds(mode, phase, remainingSeconds));

// ----------------------------
// Node status
// ----------------------------
node.status({
  fill: "blue",
  shape: "dot",
  text: `${phase.toUpperCase()} | ${minutesLeft} min left | ${currentPowerW} W`
});

// ----------------------------
// Map internal vars to AsyncAPI-required names
// ----------------------------
const remainingTime = minutesLeft;    // minutes
const waterUsed = waterLiters;        // liters
const energy = energyKwh;             // kWh
const currentPower = currentPowerW;   // Watts

// --- Telemetry payload (as your AsyncAPI expects) ---
msg.payload = {
  device: 'laundry',
  power: 'ON',
  running,
  mode,
  phase,
  waterTemp: parseFloat(waterTemp.toFixed(1)),
  spinSpeed,
  remainingTime,
  loadWeight: parseFloat(loadWeight.toFixed(1)),
  waterUsed: parseFloat(waterUsed.toFixed(2)),
  energyUsed: parseFloat(energy.toFixed(3)),
  currentPower: currentPower,
  doorStatus
};
msg.parameters = {homeId: 1};

return msg;

// === Dehumidifier Telemetry Simulator (Smart Plug Controlled) ===
// Rule: 1 execution (tick) = 1 simulated minute

// ----------------------------
// Constants / helpers
// ----------------------------
const TICK_SECONDS = 60;

const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
const toNum = (v, fallback) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : fallback;
};

// ----------------------------
// Smart plug gate (normalize!)
// ----------------------------
const plugState = String(global.get("dehumidifierState") ?? "off").trim().toLowerCase();
if (plugState !== "on") {
  node.status({ fill: "grey", shape: "ring", text: `Plug OFF – telemetry paused (${plugState})` });
  return null;
}

// ----------------------------
// Inputs (environment)
// ----------------------------
const envHumidity = clamp(toNum(msg.payload?.humidity, 70), 0, 100); // %
const envTemp = toNum(msg.payload?.temperature, 22);                 // °C

// ----------------------------
// Control settings (persistable)
// ----------------------------
const targetHumidity = clamp(toNum(flow.get("dehumidifier.targetHumidity"), 50), 20, 80);
const hysteresis = clamp(toNum(flow.get("dehumidifier.hysteresis"), 3), 1, 10);

const startThreshold = targetHumidity + hysteresis;
const stopThreshold  = targetHumidity - hysteresis;

const tankCapacity = clamp(toNum(flow.get("dehumidifier.tankCapacity"), 2.0), 0.5, 10.0);

// ----------------------------
// Persistent state
// ----------------------------
let running = flow.get("dehumidifier.running");
if (typeof running !== "boolean") running = false; // better default

let tankLevel = clamp(toNum(flow.get("dehumidifier.tankLevel"), 0), 0, tankCapacity);
let energyKwh = Math.max(0, toNum(flow.get("energy.dehumidifier"), 0));
// ----------------------------
// Tank full logic
// ----------------------------
let tankFull = tankLevel >= tankCapacity;

if (tankFull) {
  running = false;
}

// ----------------------------
// Auto start/stop (humidity hysteresis)
// ----------------------------
if (!tankFull) {
  if (!running && envHumidity >= startThreshold) {
    running = true;
  } else if (running && envHumidity <= stopThreshold) {
    running = false;
  }
}


// ----------------------------
// Fan speed + power model
// ----------------------------
let fanSpeed = "off";
let currentPowerW = 0;

if (running) {
  const delta = envHumidity - targetHumidity;

  fanSpeed = delta >= 10 ? "high"
           : delta >= 5  ? "medium"
           : "low";

  currentPowerW = fanSpeed === "high" ? 260
               : fanSpeed === "medium" ? 220
               : 180;
}

// ----------------------------
// Moisture removal & tank fill (liters per minute)
// ----------------------------
if (running) {
  const delta = Math.max(0, envHumidity - targetHumidity);

  // liters/min between 0.01 and 0.05 depending on delta
  const litersPerMin = clamp(0.01 + (delta / 50) * 0.04, 0.01, 0.05);

  tankLevel = clamp(tankLevel + litersPerMin, 0, tankCapacity);

  if (tankLevel >= tankCapacity) {
    tankFull = true;
    running = false;
    fanSpeed = "off";
    currentPowerW = 0;
  }
}

// ----------------------------
// Energy integration (kWh) - only when power > 0
// ----------------------------
if (currentPowerW > 0) {
  energyKwh += (currentPowerW / 1000) * (TICK_SECONDS / 3600);
}

// ----------------------------
// Persist state
// ----------------------------
flow.set("dehumidifier.running", running);
flow.set("dehumidifier.tankLevel", tankLevel);
flow.set("energy.dehumidifier", energyKwh);

// ----------------------------
// Status
// ----------------------------
const statusText = tankFull
  ? `TANK FULL | ${tankLevel.toFixed(2)}/${tankCapacity} L | 0 W`
  : running
    ? `RUNNING (${fanSpeed}) | ${envHumidity.toFixed(1)}% → ${targetHumidity}% | ${currentPowerW} W`
    : `IDLE | ${envHumidity.toFixed(1)}% → ${targetHumidity}% | 0 W`;

node.status({
  fill: tankFull ? "red" : (running ? "blue" : "green"),
  shape: running ? "dot" : "ring",
  text: statusText
});

// ----------------------------
// Telemetry payload
// ----------------------------
msg.payload = {
  device: "dehumidifier",
  power: plugState, // smart plug on/off
  running,
  mode: "auto",
  targetHumidity: parseFloat(targetHumidity.toFixed(1)),
  humidity: parseFloat(envHumidity.toFixed(1)),
  temperature: parseFloat(envTemp.toFixed(1)),
  fanSpeed,
  currentPower: currentPowerW,
  tankLevel: parseFloat(tankLevel.toFixed(2)),
  tankCapacity,
  tankFull,
  energyUsed: parseFloat(energyKwh.toFixed(3)),
  unit: "%",
  timestamp: new Date().toISOString()
};
msg.parameters = {homeId: 1};

return msg;

// === Cooker/Oven Telemetry Simulator (30 min Bake Mode) ===
// Rule: 1 execution (tick) = 1 simulated minute

// ----------------------------
// Helpers / constants
// ----------------------------
const TICK_SECONDS = 60;             // 1 simulated minute per tick
const MODE = "bake";
const CYCLE_SECONDS = 30 * 60;       // 30 simulated minutes

// ----------------------------
// Smart plug gate (normalized)
// ----------------------------
const plugState = String(global.get("cookerState") ?? "off").trim().toLowerCase();
if (plugState !== "on") {
  node.status({ fill: "grey", shape: "ring", text: `Plug OFF – telemetry paused (${plugState})` });
  return null;
}

// ----------------------------
// Load / init persistent timer
// ----------------------------
let remainingSeconds = flow.get("cooker.remainingSeconds");
if (remainingSeconds === undefined || remainingSeconds === null) {
  remainingSeconds = CYCLE_SECONDS;
}

// ----------------------------
// Run cycle + auto-restart when finished
// ----------------------------
let running = remainingSeconds > 0;

// Decrement timer by 1 simulated minute
if (running) {
  remainingSeconds = Math.max(0, remainingSeconds - TICK_SECONDS);
  running = remainingSeconds > 0;
}

// Auto-restart immediately when cycle ends
if (!running && remainingSeconds === 0) {
  remainingSeconds = CYCLE_SECONDS;
  running = true;
}

// Persist timer
flow.set("cooker.remainingSeconds", remainingSeconds);

// ----------------------------
// Temperatures / power
// ----------------------------
const currentTemp = running ? 180 : 25;
const setTemp = running ? 200 : 0;
const currentPowerW = running ? 1500 : 0;

// ----------------------------
// Energy (kWh cumulative)
// ----------------------------
let energyKwh = flow.get("energy.cooker") || 0;
energyKwh += (currentPowerW / 1000) * (TICK_SECONDS / 3600);
flow.set("energy.cooker", energyKwh);

// ----------------------------
// Status
// ----------------------------
const minutesLeft = Math.ceil(remainingSeconds / 60);

const statusText = running
  ? `${MODE.toUpperCase()} | ${currentTemp}°C → ${setTemp}°C | ${minutesLeft} min left | ${currentPowerW} W`
  : `OFF | Temp: ${currentTemp}°C | 0 W`;

node.status({
  fill: running ? "orange" : "grey",
  shape: running ? "dot" : "ring",
  text: statusText
});

// ----------------------------
// Telemetry payload
// ----------------------------
msg.payload = {
  device: "cooker",
  power: running ? "ON" : "OFF",
  mode: MODE,
  setTemp,
  currentTemp,
  remainingTime: minutesLeft,                 // minutes
  currentPower: currentPowerW,                // W
  energyUsed: parseFloat(energyKwh.toFixed(3)),
  timestamp: new Date().toISOString()
};
msg.parameters = {homeId: 1};

return msg;

// === Thermostat / HVAC Telemetry (Smart Plug Controlled) ===

// --- Check Smart Plug state before running ---
const plugState = global.get('thermostatState') || 'off';
if (plugState !== 'on') {
    node.status({ fill: 'grey', shape: 'ring', text: 'Plug OFF – telemetry paused' });
    return null;
}

// --- Read environment values from input ---
let envTemp = parseFloat(msg.payload.temperature ?? 22);
let envHumidity = parseFloat(msg.payload.humidity ?? 45);

// --- Desired temperature (fixed setpoint) ---
let desired = flow.get('thermostat.setpoint') ?? 23;
flow.set('thermostat.setpoint', desired);

// --- Persistent current temperature (don’t reset every tick) ---
let current = flow.get('thermostat.currentTemp');
if (current === undefined || current === null) current = envTemp;

// --- Simulation step: 1 execution = 1 simulated minute ---
const tickDuration = 60; // seconds (simulated)

// --- Small natural drift toward environment ---
current += (Math.random() * 0.4 - 0.2); // ±0.2°C
current += (envTemp - current) * 0.05;  // gently pull toward env

// --- Determine HVAC mode ---
let mode = 'idle';
let currentPower = 0; // Watts

const deadband = 1; // ±1°C deadband around setpoint

if (current < desired - deadband) {
    mode = 'heat';
    currentPower = 2000;
    current += 0.4; // heating effect per tick
} else if (current > desired + deadband) {
    mode = 'cool';
    currentPower = 1200;
    current -= 0.4; // cooling effect per tick
}

// --- Energy tracking (cumulative kWh) ---
let energy = flow.get('energy.thermostat') || 0;
function wattToKwh(powerWatts, seconds) {
    return (powerWatts / 1000) * (seconds / 3600);
}
if (currentPower > 0) energy += wattToKwh(currentPower, tickDuration);

// --- Save state ---
flow.set('energy.thermostat', energy);
flow.set('thermostat.currentTemp', current);
flow.set('current_temp', current); // if you use it elsewhere

// --- Node status for visual feedback ---
let color = 'green';
let shape = 'ring';
let text = `IDLE | ${current.toFixed(1)}°C → ${desired}°C | 0 W`;

if (mode === 'heat') {
    color = 'red';
    shape = 'dot';
    text = `HEAT | ${current.toFixed(1)}°C → ${desired}°C | ${currentPower} W`;
} else if (mode === 'cool') {
    color = 'blue';
    shape = 'dot';
    text = `COOL | ${current.toFixed(1)}°C → ${desired}°C | ${currentPower} W`;
}

node.status({ fill: color, shape, text });

// --- Telemetry output ---
msg.payload = {
    device: "thermostat",
    power: plugState, // on/off (smart plug)
    temperature: parseFloat(current.toFixed(1)), // simulated current temp
    humidity: envHumidity,
    setpoint: desired,
    mode,
    energyUsed: parseFloat(energy.toFixed(3)), // cumulative kWh
    currentPower, //Numberinstantaneous Watts
    unit: "C",
    timestamp: new Date().toISOString(),
};
msg.parameters = {homeId: 1};

return msg;

