const simHours = Math.floor(simMinutesTotal / 60) % 24;
const simMinutes = simMinutesTotal % 60;

const simTimeText =
  `${String(simHours).padStart(2, "0")}:${String(simMinutes).padStart(2, "0")}`;

// Node status shows simulated clock
node.status({
  fill: "green",
  shape: "dot",
  text: `Sim Time ${simTimeText}`
});

// ----------------------------
// Realistic Environment Base
// ----------------------------
const baseTemp = 33;       // °C
const baseHumidity = 20;   // %
const hour = simHours;     // use simulated hour for lighting

// Get previous state
let currentTemp = flow.get("env.temperature");
let currentHumidity = flow.get("env.humidity");
let currentLight = flow.get("env.lightIntensity");

if (currentTemp === undefined || currentTemp === null) currentTemp = baseTemp;
if (currentHumidity === undefined || currentHumidity === null) currentHumidity = baseHumidity;
if (currentLight === undefined || currentLight === null) currentLight = 50;

// ----------------------------
// Apply small drift
// ----------------------------
currentTemp += (Math.random() * 0.4 - 0.2);       // ±0.2°C
currentHumidity += (Math.random() * 2 - 1);       // ±1%
currentHumidity = Math.max(20, Math.min(70, currentHumidity)); // clamp

// Light based on simulated time
if (hour >= 6 && hour < 18) {
  currentLight = 70 + Math.floor(Math.random() * 30); // day
} else {
  currentLight = Math.floor(Math.random() * 20);      // night
}

// Save state
flow.set("env.temperature", currentTemp);
flow.set("env.humidity", currentHumidity);
flow.set("env.lightIntensity", currentLight);
flow.set("current_temp", currentTemp);

// ----------------------------
// Output payload
// ----------------------------
msg.payload = {
  environment: true,
  temperature: parseFloat(currentTemp.toFixed(1)),
  humidity: parseFloat(currentHumidity.toFixed(1)),
  lightIntensity: currentLight,
  unit: "C",
  simulatedTime: simTimeText,        // HH:MM
  simMinutesTotal: simMinutesTotal   // optional (useful for graphs)
};

return msg;

